latest AS (SELECT business_id, account_manager, ROW_NUMBER() OVER (PARTITION BY business_id ORDER BY date DESC) rn FROM mart.v_merchant_monthly_wide WHERE date >= DATE '2026-06-01'),
owner AS (SELECT l.business_id, a.employee_id AS am_id FROM latest l JOIN alias a ON a.alias_name = l.account_manager WHERE l.rn = 1),
td AS (SELECT o.am_id, SUM(NVL(w.parcels_picked,0)) AS picked, SUM(NVL(w.delivery_revenue_total,0)) AS rev, SUM(NVL(w.parcels_delivered,0)) AS dlv
       FROM owner o JOIN mart.v_merchant_daily_wide w ON w.business_id = o.business_id AND w.date >= DATE '2026-10-01' AND w.date < DATE '2026-10-05' GROUP BY 1)
SELECT c.ancestor_id AS employee_id, e.role, COUNT(DISTINCT c.descendant_id) AS ams_below, SUM(td.picked)::bigint AS pickups_oct1_4, ROUND(SUM(td.rev)::numeric / NULLIF(SUM(td.dlv),0), 2) AS asp
FROM closure c JOIN emp e ON e.id = c.ancestor_id JOIN td ON td.am_id = c.descendant_id
WHERE e.role IN ('VP','HEAD','TL') GROUP BY 1, 2 ORDER BY 1